/* Pattern animations: a short, step-by-step "video" of each coding pattern
 * running on a tiny input. Frames are generated by running the algorithm,
 * so what you watch is the real thing, not a drawing. Play, pause, step,
 * scrub, change speed; respects reduced motion (starts paused).
 *
 * window.QFAnim.mount(container, patternName) → true if an animation exists.
 */
(function () {
  'use strict';
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const clone = x => JSON.parse(JSON.stringify(x));

  // Each generator returns { title, kind, frames: [...] }.
  // array frame: { a, ptr: {idx: label}, hi: [idx], win: [l, r], done: [idx], side: [[k, v]], sideTitle, note }
  const G = {
    'Arrays & Hashing'() {
      const a = [2, 7, 11, 15], target = 9, seen = {}, f = [];
      f.push({ a, note: `Two Sum: find two numbers adding to ${target}. One pass with a hash map of value → index.`, side: [], sideTitle: 'seen' });
      for (let i = 0; i < a.length; i++) {
        const need = target - a[i];
        f.push({ a, ptr: { [i]: 'i' }, hi: [i], side: Object.entries(seen), sideTitle: 'seen', note: `a[${i}] = ${a[i]}. Need ${need}. Is ${need} in the map?` });
        if (need in seen) {
          f.push({ a, ptr: { [i]: 'i', [seen[need]]: 'j' }, done: [i, seen[need]], side: Object.entries(seen), sideTitle: 'seen', note: `Yes — ${need} was at index ${seen[need]}. Answer [${seen[need]}, ${i}]. O(n) time, O(n) space.` });
          break;
        }
        seen[a[i]] = i;
        f.push({ a, ptr: { [i]: 'i' }, side: Object.entries(seen), sideTitle: 'seen', note: `No. Store ${a[i]} → ${i} and move on.` });
      }
      return { title: 'Two Sum with a hash map', kind: 'array', frames: f };
    },
    'Two Pointers'() {
      const a = [1, 3, 4, 6, 8, 11], t = 10, f = [];
      let l = 0, r = a.length - 1;
      f.push({ a, ptr: { [l]: 'L', [r]: 'R' }, note: `Sorted array, target ${t}. Start at both ends.` });
      while (l < r) {
        const s = a[l] + a[r];
        if (s === t) { f.push({ a, ptr: { [l]: 'L', [r]: 'R' }, done: [l, r], note: `${a[l]} + ${a[r]} = ${t}. Found it. Each step discarded one element: O(n).` }); break; }
        if (s < t) { f.push({ a, ptr: { [l]: 'L', [r]: 'R' }, hi: [l], note: `${a[l]} + ${a[r]} = ${s} < ${t}. Too small — no pair with a[L] can work, so move L right.` }); l++; }
        else { f.push({ a, ptr: { [l]: 'L', [r]: 'R' }, hi: [r], note: `${a[l]} + ${a[r]} = ${s} > ${t}. Too big — drop a[R], move R left.` }); r--; }
      }
      return { title: 'Pair with target sum', kind: 'array', frames: f };
    },
    'Sliding Window'() {
      const a = 'abcabcbb'.split(''), f = [], seen = {};
      let l = 0, best = 0, bestW = [0, 0];
      f.push({ a, note: 'Longest substring without repeating characters. Grow the window on the right; shrink from the left when it breaks the rule.' });
      for (let r = 0; r < a.length; r++) {
        while (seen[a[r]]) {
          f.push({ a, ptr: { [l]: 'L', [r]: 'R' }, win: [l, r], hi: [r], side: Object.keys(seen).map(k => [k, '✓']), sideTitle: 'in window', note: `'${a[r]}' is already in the window — shrink: drop '${a[l]}'.` });
          delete seen[a[l]]; l++;
        }
        seen[a[r]] = 1;
        if (r - l + 1 > best) { best = r - l + 1; bestW = [l, r]; }
        f.push({ a, ptr: { [l]: 'L', [r]: 'R' }, win: [l, r], side: Object.keys(seen).map(k => [k, '✓']), sideTitle: 'in window', note: `Window "${a.slice(l, r + 1).join('')}" is valid, length ${r - l + 1}. Best so far: ${best}.` });
      }
      f.push({ a, win: bestW, done: [...Array(bestW[1] - bestW[0] + 1)].map((_, i) => bestW[0] + i), note: `Answer ${best}. Each index enters and leaves once: O(n).` });
      return { title: 'Longest substring without repeats', kind: 'array', frames: f };
    },
    'Stack'() {
      const a = [73, 74, 75, 71, 69, 72, 76], ans = Array(a.length).fill(0), st = [], f = [];
      f.push({ a, note: 'Daily temperatures: days until a warmer day. Keep a stack of indices still waiting for an answer.', side: [], sideTitle: 'stack (top last)' });
      for (let i = 0; i < a.length; i++) {
        while (st.length && a[i] > a[st[st.length - 1]]) {
          const j = st.pop(); ans[j] = i - j;
          f.push({ a, ptr: { [i]: 'i', [j]: 'pop' }, hi: [j], side: st.map(x => [x, a[x]]), sideTitle: 'stack (top last)', note: `${a[i]} > ${a[j]}: day ${j} found its warmer day. Answer[${j}] = ${i - j}.` });
        }
        st.push(i);
        f.push({ a, ptr: { [i]: 'i' }, side: st.map(x => [x, a[x]]), sideTitle: 'stack (top last)', note: `Push day ${i} (${a[i]}). The stack stays decreasing.` });
      }
      f.push({ a, side: [['answer', ans.join(', ')]], sideTitle: 'result', note: 'Each index is pushed and popped once: O(n).' });
      return { title: 'Monotonic stack', kind: 'array', frames: f };
    },
    'Binary Search'() {
      const a = [1, 3, 5, 7, 9, 11, 13, 15], t = 11, f = [];
      let lo = 0, hi = a.length - 1;
      f.push({ a, ptr: { [lo]: 'lo', [hi]: 'hi' }, win: [lo, hi], note: `Find ${t}. Look at the middle; keep only the half that can still hold it.` });
      while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        f.push({ a, ptr: { [lo]: 'lo', [hi]: 'hi', [mid]: 'mid' }, win: [lo, hi], hi: [mid], note: `mid = ${mid}, a[mid] = ${a[mid]}.` });
        if (a[mid] === t) { f.push({ a, ptr: { [mid]: 'mid' }, done: [mid], note: `Found at ${mid}. ${f.length - 1} looks for ${a.length} items: O(log n).` }); break; }
        if (a[mid] < t) { lo = mid + 1; f.push({ a, ptr: { [lo]: 'lo', [hi]: 'hi' }, win: [lo, hi], note: `${a[mid]} < ${t}: discard the left half.` }); }
        else { hi = mid - 1; f.push({ a, ptr: { [lo]: 'lo', [hi]: 'hi' }, win: [lo, hi], note: `${a[mid]} > ${t}: discard the right half.` }); }
      }
      return { title: 'Binary search', kind: 'array', frames: f };
    },
    'Linked List'() {
      const n = [1, 2, 3, 4], f = [];
      // Show the list as cells; arrows flip as we reverse.
      let dir = n.map(() => '→');
      f.push({ a: n, arrows: dir.slice(), note: 'Reverse a linked list. Three pointers: prev, cur, next.' });
      for (let i = 0; i < n.length; i++) {
        f.push({ a: n, arrows: dir.slice(), ptr: { [i]: 'cur', ...(i ? { [i - 1]: 'prev' } : {}), ...(i + 1 < n.length ? { [i + 1]: 'next' } : {}) }, hi: [i], note: `Save next, point cur (${n[i]}) back at prev, then step both forward.` });
        dir[i] = '←';
        f.push({ a: n, arrows: dir.slice(), ptr: { [i]: 'prev' }, note: `${n[i]} now points ${i ? `to ${n[i - 1]}` : 'to null'}.` });
      }
      f.push({ a: n, arrows: dir, done: [n.length - 1], note: 'prev is the new head. O(n) time, O(1) space.' });
      return { title: 'Reverse a linked list', kind: 'list', frames: f };
    },
    'Intervals'() {
      const iv = [[1, 3], [2, 6], [8, 10], [15, 18]], f = [], out = [];
      f.push({ iv, out: [], note: 'Merge overlapping intervals. Sort by start, then compare each with the last merged one.' });
      for (const [s, e] of iv) {
        const last = out[out.length - 1];
        if (last && s <= last[1]) { last[1] = Math.max(last[1], e); f.push({ iv, cur: [s, e], out: clone(out), note: `[${s},${e}] overlaps [${last[0]},${last[1]}] — extend the end.` }); }
        else { out.push([s, e]); f.push({ iv, cur: [s, e], out: clone(out), note: `[${s},${e}] starts after the last end — new interval.` }); }
      }
      f.push({ iv, out: clone(out), note: `Result ${out.map(x => `[${x}]`).join(' ')}. O(n log n) for the sort.` });
      return { title: 'Merge intervals', kind: 'intervals', frames: f };
    },
    'Graphs'() {
      const g = ['11000', '11000', '00100', '00011'].map(r => r.split('').map(Number));
      const seen = g.map(r => r.map(() => 0)), f = []; let count = 0;
      f.push({ grid: clone(g), seen: clone(seen), note: 'Number of islands: scan the grid; each unvisited 1 starts a BFS that floods its island.' });
      for (let r = 0; r < g.length; r++) for (let c = 0; c < g[0].length; c++) {
        if (!g[r][c] || seen[r][c]) continue;
        count++; const q = [[r, c]]; seen[r][c] = count;
        f.push({ grid: clone(g), seen: clone(seen), at: [r, c], note: `New land at (${r},${c}) — island ${count}. Mark it visited when it joins the queue.` });
        while (q.length) {
          const [y, x] = q.shift();
          for (const [dy, dx] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
            const ny = y + dy, nx = x + dx;
            if (ny < 0 || nx < 0 || ny >= g.length || nx >= g[0].length || !g[ny][nx] || seen[ny][nx]) continue;
            seen[ny][nx] = count; q.push([ny, nx]);
            f.push({ grid: clone(g), seen: clone(seen), at: [ny, nx], note: `Spread to (${ny},${nx}).` });
          }
        }
      }
      f.push({ grid: clone(g), seen: clone(seen), note: `${count} islands. Every cell is visited once: O(rows × cols).` });
      return { title: 'BFS flood fill', kind: 'grid', frames: f };
    },
    'Advanced Graphs'() {
      const nodes = ['A', 'B', 'C', 'D'], E = { A: [['B', 4], ['C', 1]], C: [['B', 2], ['D', 5]], B: [['D', 1]], D: [] };
      const dist = { A: 0, B: Infinity, C: Infinity, D: Infinity }, done = new Set(), f = [];
      const row = () => nodes.map(n => (dist[n] === Infinity ? '∞' : dist[n]));
      f.push({ a: row(), labels: nodes, note: 'Dijkstra from A. Always settle the closest unsettled node, then relax its edges. Edges: A→B 4, A→C 1, C→B 2, C→D 5, B→D 1.' });
      while (done.size < nodes.length) {
        const u = nodes.filter(n => !done.has(n)).sort((x, y) => dist[x] - dist[y])[0];
        done.add(u);
        f.push({ a: row(), labels: nodes, hi: [nodes.indexOf(u)], done: [...done].map(n => nodes.indexOf(n)), note: `Settle ${u} at distance ${dist[u]} — the heap gives the smallest first.` });
        for (const [v, w] of E[u]) if (dist[u] + w < dist[v]) {
          dist[v] = dist[u] + w;
          f.push({ a: row(), labels: nodes, ptr: { [nodes.indexOf(v)]: 'relax' }, done: [...done].map(n => nodes.indexOf(n)), note: `${u}→${v} gives ${dist[v]}: better, update.` });
        }
      }
      f.push({ a: row(), labels: nodes, done: [0, 1, 2, 3], note: 'All shortest distances. O(E log V) with a heap.' });
      return { title: 'Dijkstra', kind: 'array', frames: f };
    },
    'Trees'() {
      // Level-order traversal of a small tree, shown level by level.
      const levels = [[3], [9, 20], [15, 7]], f = [], out = [];
      f.push({ levels, note: 'Level-order (BFS): a queue holds the next level; process a whole level at a time.' });
      levels.forEach((lv, d) => {
        out.push(lv);
        f.push({ levels, lit: d, side: out.map((x, i) => [`level ${i}`, x.join(', ')]), sideTitle: 'output', note: `Pop ${lv.length} node${lv.length > 1 ? 's' : ''} (${lv.join(', ')}); push their children for level ${d + 1}.` });
      });
      f.push({ levels, side: out.map((x, i) => [`level ${i}`, x.join(', ')]), sideTitle: 'output', note: 'O(n) time; the queue holds at most one level.' });
      return { title: 'Level-order traversal', kind: 'tree', frames: f };
    },
    'Heap / Priority Queue'() {
      const a = [3, 2, 1, 5, 6, 4], k = 2, h = [], f = [];
      f.push({ a, side: [], sideTitle: `min-heap (size ≤ ${k})`, note: `k-th largest (k=${k}): keep a min-heap of the ${k} largest seen; its top is the answer.` });
      a.forEach((x, i) => {
        h.push(x); h.sort((p, q) => p - q);
        let note = `Push ${x}.`;
        if (h.length > k) { const out = h.shift(); note += ` Heap too big — pop the smallest (${out}).`; }
        f.push({ a, ptr: { [i]: 'x' }, hi: [i], side: h.map((v, j) => [j === 0 ? 'top' : '', v]), sideTitle: `min-heap (size ≤ ${k})`, note });
      });
      f.push({ a, side: h.map((v, j) => [j === 0 ? 'top' : '', v]), sideTitle: 'min-heap', note: `Answer: top = ${h[0]}. O(n log k).` });
      return { title: 'k-th largest with a heap', kind: 'array', frames: f };
    },
    'Backtracking'() {
      const nums = [1, 2, 3], f = [], res = [];
      const go = (start, path) => {
        res.push(path.slice());
        f.push({ a: nums, hi: path.map(v => nums.indexOf(v)), side: res.map((r, i) => [i + 1, `[${r.join(',')}]`]), sideTitle: 'subsets', note: `Record [${path.join(',')}]. Try adding each later number.` });
        for (let i = start; i < nums.length; i++) {
          path.push(nums[i]);
          go(i + 1, path);
          path.pop();
          f.push({ a: nums, hi: path.map(v => nums.indexOf(v)), ptr: { [i]: 'undo' }, side: res.map((r, j) => [j + 1, `[${r.join(',')}]`]), sideTitle: 'subsets', note: `Undo ${nums[i]} — back to [${path.join(',')}].` });
        }
      };
      f.push({ a: nums, note: 'Subsets: choose → recurse → un-choose. The start index stops reuse.' });
      go(0, []);
      f.push({ a: nums, side: res.map((r, i) => [i + 1, `[${r.join(',')}]`]), sideTitle: 'subsets', note: `${res.length} subsets = 2^n. Say the exponential cost up front.` });
      return { title: 'Subsets', kind: 'array', frames: f };
    },
    '1-D Dynamic Programming'() {
      const n = 6, dp = Array(n + 1).fill(null), f = [];
      dp[0] = 1; dp[1] = 1;
      f.push({ a: dp.map(x => x ?? ''), labels: dp.map((_, i) => i), note: 'Climbing stairs: dp[i] = ways to reach step i = dp[i-1] + dp[i-2]. Base: dp[0] = dp[1] = 1.' });
      for (let i = 2; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2];
        f.push({ a: dp.map(x => x ?? ''), labels: dp.map((_, j) => j), ptr: { [i]: 'i' }, hi: [i - 1, i - 2], done: [i], note: `dp[${i}] = dp[${i - 1}] + dp[${i - 2}] = ${dp[i - 1]} + ${dp[i - 2]} = ${dp[i]}.` });
      }
      f.push({ a: dp, labels: dp.map((_, j) => j), done: [n], note: `${dp[n]} ways. O(n) time; only two values are needed, so O(1) space.` });
      return { title: 'Climbing stairs', kind: 'array', frames: f };
    },
    '2-D Dynamic Programming'() {
      const A = 'ace', B = 'abcde', f = [];
      const dp = Array.from({ length: A.length + 1 }, () => Array(B.length + 1).fill(0));
      f.push({ table: clone(dp), rows: ['', ...A], cols: ['', ...B], note: 'Longest common subsequence. dp[i][j] = LCS of the first i and j letters.' });
      for (let i = 1; i <= A.length; i++) for (let j = 1; j <= B.length; j++) {
        const match = A[i - 1] === B[j - 1];
        dp[i][j] = match ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
        f.push({ table: clone(dp), rows: ['', ...A], cols: ['', ...B], at: [i, j], from: match ? [[i - 1, j - 1]] : [[i - 1, j], [i, j - 1]],
          note: match ? `'${A[i - 1]}' = '${B[j - 1]}': diagonal + 1 = ${dp[i][j]}.` : `'${A[i - 1]}' ≠ '${B[j - 1]}': max(up, left) = ${dp[i][j]}.` });
      }
      f.push({ table: clone(dp), rows: ['', ...A], cols: ['', ...B], at: [A.length, B.length], note: `LCS = ${dp[A.length][B.length]}. O(n·m).` });
      return { title: 'Longest common subsequence', kind: 'table', frames: f };
    },
    'Greedy'() {
      const a = [2, 3, 1, 1, 4], f = []; let reach = 0;
      f.push({ a, note: 'Jump game: track the furthest index reachable so far. If you ever stand beyond it, you are stuck.' });
      for (let i = 0; i < a.length; i++) {
        if (i > reach) { f.push({ a, ptr: { [i]: 'i' }, hi: [i], note: `Index ${i} is beyond reach ${reach}: impossible.` }); break; }
        reach = Math.max(reach, i + a[i]);
        f.push({ a, ptr: { [i]: 'i' }, win: [0, Math.min(reach, a.length - 1)], note: `From ${i} you can jump ${a[i]} → furthest reach ${reach}.` });
        if (reach >= a.length - 1) { f.push({ a, done: [a.length - 1], win: [0, a.length - 1], note: 'The end is reachable. One pass, O(n).' }); break; }
      }
      return { title: 'Jump game', kind: 'array', frames: f };
    },
    'Bit Manipulation'() {
      const a = [4, 1, 2, 1, 2], f = []; let x = 0;
      const bits = v => v.toString(2).padStart(3, '0');
      f.push({ a, side: [['xor', `0 (${bits(0)})`]], sideTitle: 'running xor', note: 'Single number: XOR cancels pairs (v ^ v = 0), leaving the odd one out.' });
      a.forEach((v, i) => { x ^= v; f.push({ a, ptr: { [i]: 'i' }, hi: [i], side: [['xor', `${x} (${bits(x)})`]], sideTitle: 'running xor', note: `xor ^= ${v} (${bits(v)}) → ${x}.` }); });
      f.push({ a, side: [['answer', x]], sideTitle: 'result', note: `Answer ${x}. O(n) time, O(1) space.` });
      return { title: 'Single number with XOR', kind: 'array', frames: f };
    },
    'Tries'() {
      const words = ['car', 'cat', 'cart'], f = [], lines = [];
      f.push({ trie: [], note: 'A trie stores words letter by letter; shared prefixes share nodes.' });
      const nodes = new Set();
      for (const w of words) {
        let added = [];
        for (let i = 1; i <= w.length; i++) { const p = w.slice(0, i); if (!nodes.has(p)) { nodes.add(p); added.push(p); } }
        lines.push(w);
        f.push({ trie: [...nodes].sort(), fresh: added, ends: lines.slice(), note: `Insert "${w}": ${added.length ? `new nodes ${added.map(x => x.slice(-1)).join(', ')}` : 'no new nodes'}; mark the end of the word.` });
      }
      f.push({ trie: [...nodes].sort(), ends: lines, note: 'Prefix search walks one node per letter: O(length of the word).' });
      return { title: 'Building a trie', kind: 'trie', frames: f };
    },
    'Math & Geometry'() {
      const m = [[1, 2, 3], [4, 5, 6], [7, 8, 9]], f = [];
      const t = clone(m);
      f.push({ table: clone(t), note: 'Rotate a matrix 90° clockwise in place: transpose, then reverse each row.' });
      for (let i = 0; i < 3; i++) for (let j = i + 1; j < 3; j++) { [t[i][j], t[j][i]] = [t[j][i], t[i][j]]; f.push({ table: clone(t), at: [i, j], from: [[j, i]], note: `Transpose: swap (${i},${j}) with (${j},${i}).` }); }
      for (let i = 0; i < 3; i++) { t[i].reverse(); f.push({ table: clone(t), row: i, note: `Reverse row ${i}.` }); }
      f.push({ table: clone(t), note: 'Rotated. O(n²) time, O(1) extra space.' });
      return { title: 'Rotate image', kind: 'table', frames: f };
    },
  };

  function cellsHtml(fr) {
    const ptr = fr.ptr || {}, hi = new Set(fr.hi || []), done = new Set(fr.done || []);
    const [wl, wr] = fr.win || [-1, -2];
    return `<div class="qa-row">${fr.a.map((v, i) => `
      <div class="qa-cell${hi.has(i) ? ' hi' : ''}${done.has(i) ? ' done' : ''}${i >= wl && i <= wr ? ' win' : ''}">
        <span class="qa-v">${esc(v)}</span>${fr.arrows ? `<span class="qa-arrow">${esc(fr.arrows[i])}</span>` : ''}
        <span class="qa-i">${esc(fr.labels ? fr.labels[i] : i)}</span>
        <span class="qa-p">${ptr[i] ? esc(ptr[i]) : ''}</span></div>`).join('')}</div>`;
  }
  function sideHtml(fr) {
    if (!fr.side) return '';
    return `<div class="qa-side"><b>${esc(fr.sideTitle || '')}</b>${fr.side.length ? `<ul>${fr.side.map(([k, v]) => `<li><span>${esc(k)}</span><span>${esc(v)}</span></li>`).join('')}</ul>` : '<p>empty</p>'}</div>`;
  }
  function frameHtml(kind, fr) {
    switch (kind) {
      case 'array': case 'list': return `<div class="qa-stage">${cellsHtml(fr)}${sideHtml(fr)}</div>`;
      case 'grid': {
        const [ay, ax] = fr.at || [-1, -1];
        return `<div class="qa-stage"><div class="qa-grid" style="grid-template-columns:repeat(${fr.grid[0].length}, 40px)">${fr.grid.map((r, y) => r.map((v, x) =>
          `<div class="qa-g${v ? ' land' : ''}${fr.seen[y][x] ? ` seen s${(fr.seen[y][x] - 1) % 3}` : ''}${y === ay && x === ax ? ' at' : ''}">${fr.seen[y][x] ? fr.seen[y][x] : v}</div>`).join('')).join('')}</div></div>`;
      }
      case 'table': {
        const [ai, aj] = fr.at || [-1, -1]; const from = new Set((fr.from || []).map(([a, b]) => `${a},${b}`));
        const head = fr.cols ? `<tr><th></th>${fr.cols.map(c => `<th>${esc(c)}</th>`).join('')}</tr>` : '';
        return `<div class="qa-stage"><table class="qa-table">${head}${fr.table.map((r, i) => `<tr>${fr.rows ? `<th>${esc(fr.rows[i])}</th>` : ''}${r.map((v, j) =>
          `<td class="${i === ai && j === aj ? 'at' : ''}${from.has(`${i},${j}`) ? ' from' : ''}${fr.row === i ? ' from' : ''}">${esc(v)}</td>`).join('')}</tr>`).join('')}</table></div>`;
      }
      case 'intervals': {
        const max = 20, bar = ([s, e], cls) => `<div class="qa-iv ${cls}" style="left:${s / max * 100}%;width:${(e - s) / max * 100}%"><span>[${s},${e}]</span></div>`;
        return `<div class="qa-stage qa-ivs"><div class="qa-ivl"><b>input</b>${fr.iv.map(x => `<div class="qa-ivrow">${bar(x, fr.cur && fr.cur[0] === x[0] ? 'hi' : '')}</div>`).join('')}</div>
          <div class="qa-ivl"><b>merged</b><div class="qa-ivrow">${fr.out.map(x => bar(x, 'done')).join('')}</div></div></div>`;
      }
      case 'tree': return `<div class="qa-stage"><div class="qa-tree">${fr.levels.map((lv, d) => `<div class="qa-lv${fr.lit === d ? ' hi' : ''}${fr.lit > d ? ' done' : ''}">${lv.map(v => `<span class="qa-node">${v}</span>`).join('')}</div>`).join('')}</div>${sideHtml(fr)}</div>`;
      case 'trie': return `<div class="qa-stage"><div class="qa-trie">${fr.trie.map(p => `<div class="qa-tn${(fr.fresh || []).includes(p) ? ' hi' : ''}${(fr.ends || []).includes(p) ? ' done' : ''}" style="padding-left:${(p.length - 1) * 22}px"><span class="qa-node">${esc(p.slice(-1))}</span><small>${esc(p)}${(fr.ends || []).includes(p) ? ' ● end' : ''}</small></div>`).join('') || '<p class="qf-muted">(root)</p>'}</div></div>`;
    }
    return '';
  }

  function mount(el, pattern) {
    const gen = G[pattern];
    if (!gen || !el) return false;
    // Re-mounting into the same box (the gallery's pattern chips) must stop the
    // previous player's timer, which would otherwise keep ticking off-screen.
    el._qaStop?.();
    const { title, kind, frames } = gen();
    let i = 0, timer = null, speed = 1;
    const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
    el.innerHTML = `<figure class="qa" aria-label="Animation: ${esc(title)}">
      <figcaption><b>${esc(title)}</b><span class="qa-count" aria-live="off"></span></figcaption>
      <div class="qa-view"></div>
      <p class="qa-note" aria-live="polite"></p>
      <div class="qa-ctl">
        <button type="button" data-a="first" aria-label="Restart">⏮</button>
        <button type="button" data-a="prev" aria-label="Previous step">◀</button>
        <button type="button" data-a="play" class="qa-play" aria-label="Play">▶ Play</button>
        <button type="button" data-a="next" aria-label="Next step">▶|</button>
        <input type="range" min="0" max="${frames.length - 1}" value="0" aria-label="Step">
        <button type="button" data-a="speed" aria-label="Speed">1×</button>
      </div></figure>`;
    const view = el.querySelector('.qa-view'), note = el.querySelector('.qa-note'), count = el.querySelector('.qa-count');
    const range = el.querySelector('input[type=range]'), play = el.querySelector('.qa-play'), sp = el.querySelector('[data-a=speed]');
    const draw = () => {
      view.innerHTML = frameHtml(kind, frames[i]);
      note.textContent = frames[i].note || '';
      count.textContent = `step ${i + 1} / ${frames.length}`;
      range.value = i;
    };
    const stop = () => { clearInterval(timer); timer = null; play.textContent = '▶ Play'; play.setAttribute('aria-label', 'Play'); };
    el._qaStop = stop;
    const start = () => {
      if (i >= frames.length - 1) i = 0;
      stop(); draw();
      timer = setInterval(() => { if (!document.body.contains(el)) return stop(); if (i >= frames.length - 1) return stop(); i++; draw(); }, 1700 / speed);
      play.textContent = '❚❚ Pause'; play.setAttribute('aria-label', 'Pause');
    };
    el.querySelector('.qa-ctl').addEventListener('click', e => {
      const a = e.target.closest('[data-a]')?.dataset.a; if (!a) return;
      if (a === 'play') return timer ? stop() : start();
      if (a === 'speed') { speed = speed === 1 ? 2 : speed === 2 ? 0.5 : 1; sp.textContent = `${speed}×`; if (timer) start(); return; }
      stop();
      if (a === 'first') i = 0; if (a === 'prev') i = Math.max(0, i - 1); if (a === 'next') i = Math.min(frames.length - 1, i + 1);
      draw();
    });
    range.addEventListener('input', () => { stop(); i = +range.value; draw(); });
    draw();
    if (!reduce) start();
    return true;
  }

  window.QFAnim = { mount, has: p => Boolean(G[p]), patterns: Object.keys(G) };
})();
